/* Account identity stays in an HttpOnly cookie. Only the CSRF token is tab-scoped. */
'use strict';
const $=id=>document.getElementById(id);
let token=sessionStorage.getItem('bala-account-csrf')||'', health, busy=false, checkoutKey=null, weeklyActive=false;
function message(text){$('status').textContent=text;}
const parentPanel=document.createElement('section');parentPanel.id='parent-profile';parentPanel.className='panel';
parentPanel.innerHTML='<span class="overline">YOUR ACCOUNT</span><h2>Parent profile</h2><dl id="parent-details"></dl><form id="parent-profile-form"><label for="parent-name">Your name</label><input id="parent-name" required maxlength="80" autocomplete="name"><label for="parent-email">Email (optional)</label><input id="parent-email" type="email" maxlength="254" autocomplete="email"><p class="small muted">Your email is not verified and does not change your sign-in login. No emails are sent.</p><button class="button primary" type="submit">Save parent profile</button></form>';
$('account').prepend(parentPanel);
const securityPanel=document.createElement('section');securityPanel.className='panel';securityPanel.id='account-security';
securityPanel.innerHTML='<h2>Account security</h2><details><summary>Change password</summary><form id="change-password-form"><label for="current-password">Current password</label><input id="current-password" type="password" minlength="12" maxlength="128" required autocomplete="current-password"><label for="new-password">New password</label><input id="new-password" type="password" minlength="12" maxlength="128" required autocomplete="new-password"><label for="confirm-password">Repeat new password</label><input id="confirm-password" type="password" minlength="12" maxlength="128" required autocomplete="new-password"><p>Changing your password signs out all sessions and invalidates your saved recovery code.</p><button class="button primary" type="submit">Change password</button></form></details><details><summary>Prepare a recovery code</summary><p>Keep a one-time code somewhere private in case you forget your password. Creating a new code replaces the old one. Your email is not a recovery channel.</p><form id="recovery-code-form"><label for="recovery-password">Current password</label><input id="recovery-password" type="password" minlength="12" maxlength="128" required autocomplete="current-password"><button class="button subtle" type="submit">Create recovery code</button></form><div id="recovery-code-result" hidden><label for="recovery-code-value">Save this code privately. It is only shown here.</label><input id="recovery-code-value" readonly autocomplete="off"><button type="button" id="hide-recovery-code" class="button subtle">I have saved it; hide code</button></div></details>';
$('account').append(securityPanel);
const recover=document.createElement('details');recover.innerHTML='<summary>Forgot your password?</summary><p>Use a recovery code previously created in Account security. Without a code, self-service recovery is unavailable. No email reset is sent.</p><form id="recover-password-form"><label for="recover-login">Parent login</label><input id="recover-login" required minlength="3" maxlength="120" autocomplete="username"><label for="recover-code">One-time recovery code</label><input id="recover-code" type="password" minlength="32" maxlength="128" required autocomplete="off"><label for="recover-new">New password</label><input id="recover-new" type="password" minlength="12" maxlength="128" required autocomplete="new-password"><label for="recover-confirm">Repeat new password</label><input id="recover-confirm" type="password" minlength="12" maxlength="128" required autocomplete="new-password"><button type="submit" class="button primary">Reset password with code</button></form>';
$('authentication').append(recover);
const requestPanel=document.createElement('section');requestPanel.className='panel';requestPanel.innerHTML='<h2>Recent story requests</h2><p>Reopen a saved request to check its progress. Continuing a request may use provider credits. Completed books remain in My Storybooks.</p><ul id="recent-requests"></ul>';$('account').append(requestPanel);
function clearSecurity(){for(const id of ['change-password-form','recovery-code-form','recover-password-form'])$(id).reset();$('recovery-code-value').value='';$('recovery-code-result').hidden=true;}
async function api(path,body){
 const response=await fetch('/api/'+path,{credentials:'same-origin',cache:'no-store',method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json','X-Bala-CSRF':token},body:body===undefined?undefined:JSON.stringify(body)});
 const data=await response.json();
 if(!response.ok){if(response.status===401){lock();}throw new Error(data.error||'This action could not be completed. Please try again.');}return data;
}
function lock(){ $('account').hidden=true;$('logout').hidden=true;$('authentication').hidden=false;$('parent-profile-form').reset();$('parent-details').replaceChildren();clearSecurity();$('recent-requests').replaceChildren(); }
function list(id,items,render,empty){const root=$(id);root.replaceChildren();if(!items.length){const li=document.createElement('li');li.textContent=empty;root.append(li);return;}items.forEach(item=>{const li=document.createElement('li');render(li,item);root.append(li);});}
function date(seconds){return seconds?new Date(seconds*1000).toLocaleString():'No active weekly pass';}
async function load(){
 const me=await api('accounts/me');
 const session=await api('accounts/csrf');token=session.csrf;sessionStorage.setItem('bala-account-csrf',token);
 if(me.role!=='parent'){lock();message('This page is for parent accounts. Use your administrator workspace for management.');return;}
 const profile=me.profile||{};$('parent-name').value=profile.display_name||'';$('parent-email').value=profile.email||'';
 $('parent-details').replaceChildren();for(const [label,value] of [['Name',profile.display_name||'Not provided'],['Email',profile.email||'Not provided'],['Sign-in login',profile.login||'Unavailable'],['Account created',date(profile.created_at)]]){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;$('parent-details').append(dt,dd);}
 const [children,balance,library,receipts]=await Promise.all(['children','balance','library','billing-history'].map(p=>api('accounts/'+p)));
 list('children',children.children,(li,c)=>{li.textContent=c.name+' · age '+c.age+' ';const edit=document.createElement('button');edit.type='button';edit.className='button subtle';edit.textContent='Edit profile';edit.onclick=()=>{editingChild=c.id;$('child-name').value=c.name;$('child-age').value=c.age;$('child-form').querySelector('button').textContent='Save profile';$('child-name').focus();};const remove=document.createElement('button');remove.type='button';remove.className='button subtle';remove.textContent='Delete profile';remove.onclick=()=>{if(confirm('Delete '+c.name+'’s profile? Saved storybooks will remain in your account.'))action(async()=>{await api('accounts/children/'+encodeURIComponent(c.id)+'/delete',{confirm:true});editingChild=null;await load();message('Child profile deleted. Saved storybooks are retained.');});};li.append(edit,remove);},'Add your first little listener.');
 $('balance').replaceChildren();
 [['Free stories available',balance.starter_available],['Free story slots held',balance.starter_held],['Free stories completed',balance.starter_completed],['Weekly stories available',balance.weekly_available],['Weekly pass expires',date(balance.weekly_expires_at)]].forEach(([label,value])=>{const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;$('balance').append(dt,dd);});
 weeklyActive=Boolean(balance.weekly_expires_at);$('open-checkout').disabled=weeklyActive;
 list('receipts',receipts.receipts,(li,r)=>{li.textContent='$5 weekly pass · '+r.outcome+' · '+date(r.created_at)+' · Receipt '+r.receipt_id;},'No billing activity yet.');
 list('library',library.books,(li,b)=>{li.textContent=(b.title||'Storybook')+' · '+date(b.created_at)+' ';if(health.managedWorkflowEnabled){const open=document.createElement('a');open.textContent='Open storybook';open.href='index.html?run='+encodeURIComponent(b.run_id)+'#managed-book';const a=document.createElement('a');a.textContent='Download PDF';a.href='/api/accounts/runs/'+encodeURIComponent(b.run_id)+'/pdf?book_hash='+encodeURIComponent(b.book_hash);li.append(open,document.createTextNode(' · '),a);}else{li.append(document.createTextNode('Saved book access is not connected in this installation yet.'));}},'Your completed storybooks will appear here.');
 $('creation-status').textContent='Create stories in Story Studio. Your saved books are available below.';
 $('authentication').hidden=true;$('account').hidden=false;$('logout').hidden=false;
 requestPanel.hidden=!health.managedWorkflowEnabled;
 if(health.managedWorkflowEnabled){$('recent-requests').textContent='Loading your saved requests...';try{const data=await api('accounts/runs');list('recent-requests',data.requests,(li,r)=>{const a=document.createElement('a');a.href='index.html?run='+encodeURIComponent(r.run_id)+'#managed-book';a.textContent=(r.idea||r.objective)+' · '+r.status.replaceAll('_',' ');li.append(a);},'No story requests yet.');}catch(e){$('recent-requests').textContent='Request history could not load. Your saved books are still available.';}}
}
async function action(task){if(busy)return;busy=true;const buttons=[...document.querySelectorAll('button')],previous=buttons.map(b=>b.disabled);buttons.forEach(b=>b.disabled=true);try{await task();}catch(e){message(e.message);}finally{buttons.forEach((b,i)=>b.disabled=previous[i]);$('open-checkout').disabled=weeklyActive;busy=false;}}
$('parent-profile-form').addEventListener('submit',event=>{event.preventDefault();action(async()=>{await api('accounts/profile',{display_name:$('parent-name').value,email:$('parent-email').value.trim()||null});await load();message('Parent profile saved. Your sign-in login is unchanged.');});});
$('change-password-form').onsubmit=event=>{event.preventDefault();action(async()=>{if($('new-password').value!==$('confirm-password').value)throw Error('The new passwords do not match.');await api('accounts/password',{current_password:$('current-password').value,new_password:$('new-password').value});sessionStorage.removeItem('bala-account-csrf');token='';lock();message('Password changed. All sessions are signed out. Sign in with your new password and prepare a new recovery code.');});};
$('recovery-code-form').onsubmit=event=>{event.preventDefault();action(async()=>{const result=await api('accounts/recovery-code',{current_password:$('recovery-password').value});$('recovery-password').value='';$('recovery-code-value').value=result.recovery_code;$('recovery-code-result').hidden=false;message('Save your one-time recovery code privately. Any previous code is invalid.');});};
$('hide-recovery-code').onclick=()=>{$('recovery-code-value').value='';$('recovery-code-result').hidden=true;};
$('recover-password-form').onsubmit=event=>{event.preventDefault();action(async()=>{if($('recover-new').value!==$('recover-confirm').value)throw Error('The new passwords do not match.');token=(await api('health')).csrf;await api('accounts/recover',{login:$('recover-login').value,recovery_code:$('recover-code').value,new_password:$('recover-new').value});sessionStorage.removeItem('bala-account-csrf');token='';lock();message('Password reset. Sign in with your new password. Your recovery code has been used.');});};
$('auth-form').addEventListener('submit',e=>{e.preventDefault();const mode=e.submitter?.value||'login';action(async()=>{const credentials={login:$('login').value,password:$('password').value};token=(await api('health')).csrf;if(mode==='register')await api('accounts/register',credentials);const session=await api('accounts/login',credentials);token=session.csrf;sessionStorage.setItem('bala-account-csrf',token);$('password').value='';await load();message(mode==='register'?'Welcome! Your three starter story credits are ready.':'Welcome back.');if(mode==='login'&&new URLSearchParams(location.search).get('from')==='main'&&session.role==='parent')location.assign('index.html#create');});});
let editingChild=null;
$('child-form').addEventListener('submit',e=>{e.preventDefault();action(async()=>{await api('accounts/children'+(editingChild?'/'+encodeURIComponent(editingChild)+'/update':''),{name:$('child-name').value,age:Number($('child-age').value)});editingChild=null;$('child-form').reset();$('child-form').querySelector('button').textContent='Add child profile';await load();message('Child profile saved.');});});
$('logout').addEventListener('click',()=>action(async()=>{await api('accounts/logout',{});sessionStorage.removeItem('bala-account-csrf');token='';lock();message('You are signed out.');}));
$('open-checkout').addEventListener('click',()=>{checkoutKey=crypto.randomUUID();$('checkout-status').textContent='';$('checkout').showModal();});
$('close-checkout').addEventListener('click',()=>$('checkout').close());
$('checkout-form').addEventListener('submit',e=>{e.preventDefault();action(async()=>{const outcome=$('payment-outcome').value;await api('accounts/checkout',{request_key:checkoutKey,outcome});$('checkout').close();checkoutKey=null;await load();message(outcome==='success'?'Weekly pass confirmed. No money was charged.':outcome==='declined'?'Payment was declined. No weekly pass was added and no money was charged.':'Checkout cancelled. Your balance is unchanged.');});});
(async()=>{try{health=await api('health');if(!health.accountsEnabled){$('unavailable').hidden=false;return;}token=sessionStorage.getItem('bala-account-csrf')||'';try{await load();}catch(e){lock();if(!/Sign in|sign in/.test(e.message))message(e.message);}}catch(e){message('Account access could not be loaded. Please try again.');}})();
